Insert into PATTERNS (PATTERN_ID,USER_ID,TITLE,DESCRIPTION,NEEDLE_TYPE,DIFFICULTY,YARN_TYPE,NEEDLE_SIZE,FINISHED_SIZE,WORK_TIME,THUMBNAIL_IMG,VIEW_COUNT,CREATED_AT,UPDATED_AT,CATEGORY) values (14,41,'강아지 픽셀 뜨기','코바늘, 대바늘 상관 없는 픽셀 뜨기 도안입니다.
Insert into PATTERNS (PATTERN_ID,USER_ID,TITLE,DESCRIPTION,NEEDLE_TYPE,DIFFICULTY,YARN_TYPE,NEEDLE_SIZE,FINISHED_SIZE,WORK_TIME,THUMBNAIL_IMG,VIEW_COUNT,CREATED_AT,UPDATED_AT,CATEGORY) values (20,50,'해바라기 모티브 가방','여름에 들고 다니기 딱 좋은 해바라기 패턴 토트백이에요. 모티브를 여러 개 이어붙이는 방식이라 시간이 걸리지만 완성하면 정말 예뻐요 🌻 코튼 실을 사용하면 가방 형태가 잘 잡혀요. 안감을 달아주면 더 실용적으로 사용할 수 있어요.','코바늘','초급','코튼 혼방 실','코바늘 4호','가로 30cm x 세로 25cm','3일 정도','/uploads/patterns/pattern_1780558193672.jpg',0,to_timestamp('26/06/04 16:29:53.677000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 16:29:53.677000000','RR/MM/DD HH24:MI:SSXFF'),null);
Insert into PATTERNS (PATTERN_ID,USER_ID,TITLE,DESCRIPTION,NEEDLE_TYPE,DIFFICULTY,YARN_TYPE,NEEDLE_SIZE,FINISHED_SIZE,WORK_TIME,THUMBNAIL_IMG,VIEW_COUNT,CREATED_AT,UPDATED_AT,CATEGORY) values (17,50,'따뜻한 겨울 대바늘 양말',' 발이 시린 겨울에 딱인 대바늘 양말 도안이에요. 메리야스뜨기 기본만 알면 도전할 수 있어요. 신축성 있는 실을 사용하면 더 편안하게 신을 수 있어요. 발 사이즈는 235~245mm 기준이에요.','대바늘','중급','메리노울 혼방 4ply','2.5호','발 길이 24cm','6시간','/uploads/patterns/pattern_1780557580230.jpg',0,to_timestamp('26/06/04 16:19:40.244000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 16:19:40.244000000','RR/MM/DD HH24:MI:SSXFF'),null);
Insert into PATTERNS (PATTERN_ID,USER_ID,TITLE,DESCRIPTION,NEEDLE_TYPE,DIFFICULTY,YARN_TYPE,NEEDLE_SIZE,FINISHED_SIZE,WORK_TIME,THUMBNAIL_IMG,VIEW_COUNT,CREATED_AT,UPDATED_AT,CATEGORY) values (29,51,'대바늘 장갑','북유럽 감성 물씬 나는 장갑이에요 🦌 두 가지 색실을 번갈아 쓰는 방법만 익히면 다양한 패턴 응용이 가능해요. 완성하면 진짜 세상 예쁜 장갑이 완성돼요! 양손 합치면 약 20시간 예상이에요.','대바늘','고급','울 혼방 Fingering','2호','손 둘레 20cm 기준',' 8~10시간 (1개 기준)','/uploads/patterns/pattern_1780563454128.jpg',0,to_timestamp('26/06/04 17:57:34.151000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 17:57:34.151000000','RR/MM/DD HH24:MI:SSXFF'),null);
Insert into PATTERNS (PATTERN_ID,USER_ID,TITLE,DESCRIPTION,NEEDLE_TYPE,DIFFICULTY,YARN_TYPE,NEEDLE_SIZE,FINISHED_SIZE,WORK_TIME,THUMBNAIL_IMG,VIEW_COUNT,CREATED_AT,UPDATED_AT,CATEGORY) values (23,48,'코바늘 헤어밴드','초보자도 쉽게 만들 수 있고 완성 시간도 짧아서 선물용으로 여러 개 만들기 좋아요!','코바늘','입문','아크릴 실','5호','지름 약 15cm','1~2시간','/uploads/patterns/pattern_1780562763877.jpg',0,to_timestamp('26/06/04 17:46:03.879000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 17:46:03.879000000','RR/MM/DD HH24:MI:SSXFF'),null);
Insert into PATTERNS (PATTERN_ID,USER_ID,TITLE,DESCRIPTION,NEEDLE_TYPE,DIFFICULTY,YARN_TYPE,NEEDLE_SIZE,FINISHED_SIZE,WORK_TIME,THUMBNAIL_IMG,VIEW_COUNT,CREATED_AT,UPDATED_AT,CATEGORY) values (24,48,'여름 코바늘 마켓백','여름 장 볼 때 들고 다니기 좋은 마켓백이에요 🌿 망사 뜨기로 성기게 떠서 통기성도 좋고 가벼워요. 실을 많이 사용하지 않아서 경제적이고, 크기 조절도 쉬워요. 면 실로 뜨면 세탁기 세탁도 가능해서 실용적이에요!','코바늘','초급','코튼 실','6호',' 가로 35cm x 세로 40cm',' 4~5시간','/uploads/patterns/pattern_1780562824230.jpg',0,to_timestamp('26/06/04 17:47:04.239000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 17:47:04.239000000','RR/MM/DD HH24:MI:SSXFF'),null);
Insert into PATTERNS (PATTERN_ID,USER_ID,TITLE,DESCRIPTION,NEEDLE_TYPE,DIFFICULTY,YARN_TYPE,NEEDLE_SIZE,FINISHED_SIZE,WORK_TIME,THUMBNAIL_IMG,VIEW_COUNT,CREATED_AT,UPDATED_AT,CATEGORY) values (25,48,'포근한 코바늘 무릎담요','겨울 소파에서 덮기 딱 좋은 무릎담요예요 🛋️ 긴뜨기 반복이라 리듬감 있게 뜰 수 있어서 초보자도 도전 가능해요. 크기는 원하는 대로 조절 가능하고, 실 색상을 여러 개 써서 스트라이프 패턴으로 만들면 더 예뻐요!','코바늘','초급','벌키 아크릴 실','8호','70cm x 90cm','10~12시간','/uploads/patterns/pattern_1780562881231.jpg',0,to_timestamp('26/06/04 17:48:01.249000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 17:48:01.249000000','RR/MM/DD HH24:MI:SSXFF'),null);
Insert into PATTERNS (PATTERN_ID,USER_ID,TITLE,DESCRIPTION,NEEDLE_TYPE,DIFFICULTY,YARN_TYPE,NEEDLE_SIZE,FINISHED_SIZE,WORK_TIME,THUMBNAIL_IMG,VIEW_COUNT,CREATED_AT,UPDATED_AT,CATEGORY) values (13,21,'코바늘 체커 모자','흑백 체커보드 패턴의 코바늘 버킷햇이에요. 짧은뜨기로 빼곡하게 채워 형태감이 탄탄하고, 배색 뜨기로 체크 패턴을 표현해요. 중급 난이도지만 패턴이 규칙적이라 익숙해지면 리듬감 있게 뜰 수 있어요. 여름철 데일리 아이템으로 딱이에요!','코바늘','입문','면사 (코튼사) 흑/백 2색','6mm ','머리 둘레 56~58cm','2-3시간','/uploads/patterns/pattern_1780364158763.jpg',0,to_timestamp('26/06/02 10:35:58.774000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 15:09:36.433000000','RR/MM/DD HH24:MI:SSXFF'),null);
Insert into PATTERNS (PATTERN_ID,USER_ID,TITLE,DESCRIPTION,NEEDLE_TYPE,DIFFICULTY,YARN_TYPE,NEEDLE_SIZE,FINISHED_SIZE,WORK_TIME,THUMBNAIL_IMG,VIEW_COUNT,CREATED_AT,UPDATED_AT,CATEGORY) values (44,50,'멋스러운 코바늘 가방 만들기','멋스러운 가방을 만들 수 있는 도안이에요 ','코바늘','중급','라탄실','5호','줄 제외 25m','2일','/uploads/patterns/pattern_1780984226611.jpg',0,to_timestamp('26/06/09 14:50:26.619000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/09 14:50:26.619000000','RR/MM/DD HH24:MI:SSXFF'),null);
Insert into PATTERNS (PATTERN_ID,USER_ID,TITLE,DESCRIPTION,NEEDLE_TYPE,DIFFICULTY,YARN_TYPE,NEEDLE_SIZE,FINISHED_SIZE,WORK_TIME,THUMBNAIL_IMG,VIEW_COUNT,CREATED_AT,UPDATED_AT,CATEGORY) values (12,21,'코바늘 네트백 (마르쉐백)','코바늘로 뜨는 감성 네트백입니다. 
Insert into PATTERNS (PATTERN_ID,USER_ID,TITLE,DESCRIPTION,NEEDLE_TYPE,DIFFICULTY,YARN_TYPE,NEEDLE_SIZE,FINISHED_SIZE,WORK_TIME,THUMBNAIL_IMG,VIEW_COUNT,CREATED_AT,UPDATED_AT,CATEGORY) values (18,50,'오버핏 크루넥 스웨터','요즘 유행하는 오버핏 크루넥 스웨터 도안이에요. 박시한 실루엣이라 남녀 모두 입기 좋아요. 게이지 확인 필수예요! 실 색상에 따라 분위기가 많이 달라지니까 취향껏 골라보세요 🧶 완성하면 진짜 뿌듯한 아이템이에요.','대바늘','고급','램스울 Aran','5호','가슴 110cm (프리사이즈)','약 40~50시간','/uploads/patterns/pattern_1780558006907.jpg',0,to_timestamp('26/06/04 16:26:46.931000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 16:26:46.931000000','RR/MM/DD HH24:MI:SSXFF'),null);
Insert into PATTERNS (PATTERN_ID,USER_ID,TITLE,DESCRIPTION,NEEDLE_TYPE,DIFFICULTY,YARN_TYPE,NEEDLE_SIZE,FINISHED_SIZE,WORK_TIME,THUMBNAIL_IMG,VIEW_COUNT,CREATED_AT,UPDATED_AT,CATEGORY) values (21,50,'아기자기 코바늘 곰인형','선물용으로 딱인 코바늘 곰인형 도안이에요 🐻 짧은뜨기만 할 줄 알면 도전 가능해요! 솜을 꽉꽉 채워 넣으면 포동포동하게 완성돼요. 눈은 안전 단추를 사용하면 더 귀엽고, 아이 선물용이라면 자수로 대체하는 걸 추천해요. 실 색상만 바꿔도 분위기가 완전히 달라지니까 다양하게 만들어보세요!','코바늘','초급','아크릴 혼방 실','코바늘 8호','높이 약 20cm','약 5~6시간','/uploads/patterns/pattern_1780561905770.jpg',0,to_timestamp('26/06/04 17:31:45.776000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 17:31:45.776000000','RR/MM/DD HH24:MI:SSXFF'),null);
Insert into PATTERNS (PATTERN_ID,USER_ID,TITLE,DESCRIPTION,NEEDLE_TYPE,DIFFICULTY,YARN_TYPE,NEEDLE_SIZE,FINISHED_SIZE,WORK_TIME,THUMBNAIL_IMG,VIEW_COUNT,CREATED_AT,UPDATED_AT,CATEGORY) values (41,46,'🐰 코바늘 미니 토끼 인형 도안','완성 크기는 약 15cm 정도이고 손바닥에 쏙 들어오는 사이즈예요.
Insert into PATTERNS (PATTERN_ID,USER_ID,TITLE,DESCRIPTION,NEEDLE_TYPE,DIFFICULTY,YARN_TYPE,NEEDLE_SIZE,FINISHED_SIZE,WORK_TIME,THUMBNAIL_IMG,VIEW_COUNT,CREATED_AT,UPDATED_AT,CATEGORY) values (42,46,'🐰 코바늘 amigurumi 토끼 인형이에요!','만들고 나서 너무 귀여워서 올려봐요 ㅎㅎ 처음엔 귀 모양 잡는 게 어려웠는데 철사 넣으니까 원하는 대로 잡혀서 좋았어요!
Insert into PATTERNS (PATTERN_ID,USER_ID,TITLE,DESCRIPTION,NEEDLE_TYPE,DIFFICULTY,YARN_TYPE,NEEDLE_SIZE,FINISHED_SIZE,WORK_TIME,THUMBNAIL_IMG,VIEW_COUNT,CREATED_AT,UPDATED_AT,CATEGORY) values (22,45,' 클래식 브이넥 대바늘 가디건','봄가을에 걸치기 딱 좋은 클래식한 브이넥 가디건이에요 🍂 앞판 두 장, 뒤판 한 장, 소매 두 장을 따로 뜬 다음 이어붙이는 방식이에요. 게이지 확인이 정말 중요한 도안이니까 꼭 스와치 먼저 떠보세요! 단추 구멍도 포함되어 있어서 예쁜 단추 고르는 재미도 있어요. 완성하면 매일 입고 싶은 아이템이 될 거예요 🧶','대바늘','고급','코튼 혼방','4호','가슴 100cm (프리사이즈)','50시간','/uploads/patterns/pattern_1780562413039.jpg',0,to_timestamp('26/06/04 17:40:13.081000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 17:40:13.081000000','RR/MM/DD HH24:MI:SSXFF'),null);
Insert into PATTERNS (PATTERN_ID,USER_ID,TITLE,DESCRIPTION,NEEDLE_TYPE,DIFFICULTY,YARN_TYPE,NEEDLE_SIZE,FINISHED_SIZE,WORK_TIME,THUMBNAIL_IMG,VIEW_COUNT,CREATED_AT,UPDATED_AT,CATEGORY) values (26,48,'케이블 패턴 대바늘 목도리','꼬임 패턴이 고급스러운 케이블 목도리예요 🧣 케이블 바늘 하나만 추가로 준비하면 돼요. 한 번 익히면 다른 케이블 도안에도 응용할 수 있어서 연습용으로 추천해요. 두꺼운 실로 뜨면 금방 완성되고 따뜻함도 최고예요!','대바늘','중급','메리노울','8호','길이 160cm x 너비 20cm','8~10시간','/uploads/patterns/pattern_1780562955490.jpg',0,to_timestamp('26/06/04 17:49:15.496000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 17:49:15.496000000','RR/MM/DD HH24:MI:SSXFF'),null);
Insert into PATTERNS (PATTERN_ID,USER_ID,TITLE,DESCRIPTION,NEEDLE_TYPE,DIFFICULTY,YARN_TYPE,NEEDLE_SIZE,FINISHED_SIZE,WORK_TIME,THUMBNAIL_IMG,VIEW_COUNT,CREATED_AT,UPDATED_AT,CATEGORY) values (27,48,'심플 대바늘 비니','처음 대바늘 시작하는 분들께 추천하는 비니 도안이에요 🎿 메리야스뜨기와 고무뜨기만 할 줄 알면 완성할 수 있어요. 두꺼운 실로 뜨면 하루 만에 완성도 가능해요. 색상만 바꾸면 가족 모두에게 선물하기 좋은 아이템이에요!','대바늘','초급','아크릴 혼방','7호','머리 둘레 56cm 기준',' 3~4시간','/uploads/patterns/pattern_1780563139311.jpg',0,to_timestamp('26/06/04 17:52:19.332000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 17:52:19.332000000','RR/MM/DD HH24:MI:SSXFF'),null);
Insert into PATTERNS (PATTERN_ID,USER_ID,TITLE,DESCRIPTION,NEEDLE_TYPE,DIFFICULTY,YARN_TYPE,NEEDLE_SIZE,FINISHED_SIZE,WORK_TIME,THUMBNAIL_IMG,VIEW_COUNT,CREATED_AT,UPDATED_AT,CATEGORY) values (28,48,'손목 워머','손가락은 자유롭고 손목은 따뜻한 손목 워머예요 🤍 고무뜨기로 신축성 있게 뜨는 게 포인트예요. 엄지손가락 구멍만 신경 쓰면 나머지는 단순 반복이라 드라마 보면서 뜨기 좋아요. 두 개 합치면 약 6시간이면 완성!','대바늘','중급','메리노울 ','3.5호','길이 20cm',' 2~3시간 (1개 기준)','/uploads/patterns/pattern_1780563336917.jpg',0,to_timestamp('26/06/04 17:55:36.925000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 17:55:36.925000000','RR/MM/DD HH24:MI:SSXFF'),null);
Insert into PATTERNS (PATTERN_ID,USER_ID,TITLE,DESCRIPTION,NEEDLE_TYPE,DIFFICULTY,YARN_TYPE,NEEDLE_SIZE,FINISHED_SIZE,WORK_TIME,THUMBNAIL_IMG,VIEW_COUNT,CREATED_AT,UPDATED_AT,CATEGORY) values (30,51,'대바늘 패턴 양말','발목에 예쁜 무늬를 넣은 대바늘 양말이에요 🌸 뒤꿈치 부분은 플랩 힐 방식으로 내구성이 좋아요. 무늬 부분은 차트를 보면서 뜨면 어렵지 않아요. 양말 바늘 4개 또는 매직루프 방식으로 뜰 수 있어요. 완성하면 신고 다니기 아까울 정도로 예뻐요 🧦','대바늘','고급','울 혼방 Fingering','2호','발 길이 24cm 기준','약 12~15시간 (1켤레 기준)','/uploads/patterns/pattern_1780563591716.jpg',0,to_timestamp('26/06/04 17:59:51.726000000','RR/MM/DD HH24:MI:SSXFF'),to_timestamp('26/06/04 17:59:51.726000000','RR/MM/DD HH24:MI:SSXFF'),null);
